            C('OR1', 'R259', "I was ordered to proceed with my command to the brigade, which was stationed behind a stone fence in front of Cemetery Hill", note="late 1 Jul"),
            C('OR1', 'R256', "assembled at the cemetery behind the stone fence", note="Lt. Col. Dobke, 45th New York, evening of 1 Jul"),
